-- Quote presentation for 57 reviewed sayings; no quotation text is replaced.
do $titles$
declare edits jsonb := '[{"id":"kb_311","before_title":"「知らざるを知らずと為す、是れ知るなり」","after_title":"知らざるを知らずと為す、是れ知るなり"},{"id":"kb_298","before_title":"「過ちて改めざる、是を過ちと謂う」","after_title":"過ちて改めざる、是を過ちと謂う"},{"id":"kb_304","before_title":"「巧言令色、鮮なし仁」","after_title":"巧言令色、鮮なし仁"},{"id":"kb_624","before_title":"「己の欲せざる所、人に施すこと勿れ」","after_title":"己の欲せざる所、人に施すこと勿れ"},{"id":"kb_622","before_title":"「三人行えば、必ず我が師あり」","after_title":"三人行えば、必ず我が師あり"},{"id":"kb_625","before_title":"「学びて思わざれば則ち罔し、思いて学ばざれば則ち殆うし」","after_title":"学びて思わざれば則ち罔し、思いて学ばざれば則ち殆うし"},{"id":"kb_299","before_title":"「和して同ぜず」","after_title":"和して同ぜず"},{"id":"kb_623","before_title":"「過ぎたるは猶及ばざるが如し」","after_title":"過ぎたるは猶及ばざるが如し"},{"id":"kb_617","before_title":"「自分を知る者は明らかである」","after_title":"自分を知る者は明らかである"},{"id":"kb_618","before_title":"「足るを知る者は富む」","after_title":"足るを知る者は富む"},{"id":"kb_619","before_title":"「人に勝つ者は力があり、自分に勝つ者は強い」","after_title":"人に勝つ者は力があり、自分に勝つ者は強い"},{"id":"kb_620","before_title":"「千里の道も足下から始まる」","after_title":"千里の道も足下から始まる"},{"id":"kb_621","before_title":"「柔よく剛を制す」","after_title":"柔よく剛を制す"},{"id":"kb_312","before_title":"「桃李もの言わざれども、下自ずから蹊を成す」","after_title":"桃李もの言わざれども、下自ずから蹊を成す"},{"id":"kb_701","before_title":"「生きることを引き受けて歩む」","after_title":"生きることを引き受けて歩む"},{"id":"kb_702","before_title":"「暮らしにくさの中で、視点を探す」","after_title":"暮らしにくさの中で、視点を探す"},{"id":"kb_604","before_title":"「自分にできることと、できないことを分ける」","after_title":"自分にできることと、できないことを分ける"},{"id":"kb_603","before_title":"「人は物事そのものではなく、それについての判断に悩まされる」","after_title":"人は物事そのものではなく、それについての判断に悩まされる"},{"id":"kb_606","before_title":"「与えられた役を、よく演じる」","after_title":"与えられた役を、よく演じる"},{"id":"kb_605","before_title":"「自分で勝てない勝負には入らない」","after_title":"自分で勝てない勝負には入らない"},{"id":"kb_607","before_title":"「起きたことから利益を引き出せるかは自分次第である」","after_title":"起きたことから利益を引き出せるかは自分次第である"},{"id":"kb_615","before_title":"「運命は、従う者を導き、抗う者を引きずる」","after_title":"運命は、従う者を導き、抗う者を引きずる"},{"id":"kb_608","before_title":"「障害は、行動を前へ進める材料になる」","after_title":"障害は、行動を前へ進める材料になる"},{"id":"kb_609","before_title":"「外の出来事より、それに与える判断が自分を動かす」","after_title":"外の出来事より、それに与える判断が自分を動かす"},{"id":"kb_611","before_title":"「他人が何を考えているかより、自分の心を整える」","after_title":"他人が何を考えているかより、自分の心を整える"},{"id":"kb_610","before_title":"「今この瞬間を、最後の行為のように行う」","after_title":"今この瞬間を、最後の行為のように行う"},{"id":"kb_612","before_title":"「人生が短いのではない。多くを浪費している」","after_title":"人生が短いのではない。多くを浪費している"},{"id":"kb_613","before_title":"「正しく使えば、人生は十分に長い」","after_title":"正しく使えば、人生は十分に長い"},{"id":"kb_614","before_title":"「苦しむ前から苦しむ者は、必要以上に苦しむ」","after_title":"苦しむ前から苦しむ者は、必要以上に苦しむ"},{"id":"kb_616","before_title":"「われわれが恐れるものは、現実より想像の中に多い」","after_title":"われわれが恐れるものは、現実より想像の中に多い"},{"id":"kb_626","before_title":"「知彼知己、百戦殆うからず」","after_title":"知彼知己、百戦殆うからず"},{"id":"kb_627","before_title":"「勝兵は先ず勝ちて而る後に戦いを求む」","after_title":"勝兵は先ず勝ちて而る後に戦いを求む"},{"id":"kb_503","before_title":"「勝ちやすい条件を先に整える」","after_title":"勝ちやすい条件を先に整える"},{"id":"kb_628","before_title":"「善く戦う者は、勝ち易きに勝つ」","after_title":"善く戦う者は、勝ち易きに勝つ"},{"id":"kb_504","before_title":"「優れた勝利は、目立たない」","after_title":"優れた勝利は、目立たない"},{"id":"kb_490","before_title":"「戦わずに目的を遂げる」","after_title":"戦わずに目的を遂げる"},{"id":"kb_505","before_title":"「危機を招かない備えを重ねる」","after_title":"危機を招かない備えを重ねる"},{"id":"kb_496","before_title":"「長引く戦いに、巧みな勝ち方はない」","after_title":"長引く戦いに、巧みな勝ち方はない"},{"id":"kb_630","before_title":"「小敵の堅は、大敵の擒なり」","after_title":"小敵の堅は、大敵の擒なり"},{"id":"kb_629","before_title":"「兵に常勢なく、水に常形なし」","after_title":"兵に常勢なく、水に常形なし"},{"id":"kb_549","before_title":"「水に常形無く」","after_title":"水に常形無く"},{"id":"kb_333","before_title":"「人間万事塞翁が馬」","after_title":"人間万事塞翁が馬"},{"id":"kb_334","before_title":"「禍福は糾える縄の如し」","after_title":"禍福は糾える縄の如し"},{"id":"kb_336","before_title":"「明日は明日の風が吹く」","after_title":"明日は明日の風が吹く"},{"id":"kb_335","before_title":"「案ずるより産むが易し」","after_title":"案ずるより産むが易し"},{"id":"kb_301","before_title":"「雨降って地固まる」","after_title":"雨降って地固まる"},{"id":"kb_300","before_title":"「親しき仲にも礼儀あり」","after_title":"親しき仲にも礼儀あり"},{"id":"kb_296","before_title":"「情けは人の為ならず」","after_title":"情けは人の為ならず"},{"id":"kb_631","before_title":"「井の中の蛙、大海を知らず」","after_title":"井の中の蛙、大海を知らず"},{"id":"kb_327","before_title":"「継続は力なり」","after_title":"継続は力なり"},{"id":"kb_324","before_title":"「巧遅は拙速に如かず」","after_title":"巧遅は拙速に如かず"},{"id":"kb_315","before_title":"「鶏口となるも牛後となるなかれ」","after_title":"鶏口となるも牛後となるなかれ"},{"id":"kb_469","before_title":"「狡兎死して走狗烹らる」","after_title":"狡兎死して走狗烹らる"},{"id":"kb_468","before_title":"「鳥尽きて良弓蔵れ」","after_title":"鳥尽きて良弓蔵れ"},{"id":"kb_359","before_title":"「一つの籠にすべての卵を盛るな」","after_title":"一つの籠にすべての卵を盛るな"},{"id":"kb_329","before_title":"「完璧は善の敵」","after_title":"完璧は善の敵"},{"id":"kb_326","before_title":"「為せば成る、為さねば成らぬ何事も」","after_title":"為せば成る、為さねば成らぬ何事も"}]'::jsonb;
begin
  if jsonb_array_length(edits)<>57 or
    (select count(distinct x->>'id') from jsonb_array_elements(edits) x)<>57 then
    raise exception 'Expected 57 reviewed saying titles';
  end if;
  perform t.id from public.theories t join jsonb_to_recordset(edits) e(id text) on t.id=e.id for update of t;
  if (select count(*) from public.theories t join jsonb_to_recordset(edits) e(id text) on t.id=e.id
      where t.status='published' and t.category_id='classics-thought' and t.quotation is null)<>57 or
    exists(select 1 from public.theories t join jsonb_to_recordset(edits)
      e(id text,before_title text,after_title text) on t.id=e.id
      where t.title is distinct from e.before_title and t.title is distinct from e.after_title) then
    raise exception 'Reviewed saying title changed';
  end if;
  update public.theories t set title=e.after_title,updated_at=now()
  from jsonb_to_recordset(edits) e(id text,after_title text)
  where t.id=e.id and t.title is distinct from e.after_title;
end $titles$;
